import { Hono } from "hono";
import { notFound } from "../errors";
import type { ApiEnv } from "../types";

/** Keys generated by the R2 store: ULID (Crockford) + allowed extension. Anything else is 404. */
const VALID_KEY = /^[0-9A-HJKMNP-TV-Z]{26}\.(jpg|png|webp)$/;

/** The content-type comes from the (already validated) extension, never from the metadata stored in R2. */
const TYPE_BY_EXTENSION: Record<string, string> = {
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
};

export const imgRoutes = new Hono<ApiEnv>().get("/:key", async (c) => {
  const key = c.req.param("key");
  const extension = VALID_KEY.exec(key)?.[1];
  const type = extension === undefined ? undefined : TYPE_BY_EXTENSION[extension];
  if (type === undefined) return notFound(c);
  const object = await c.env.IMAGENES.get(key);
  if (object === null) return notFound(c);
  const headers = new Headers();
  headers.set("content-type", type);
  // Defense in depth: the browser must not "guess" another type or run anything on this origin.
  headers.set("x-content-type-options", "nosniff");
  headers.set("content-security-policy", "default-src 'none'");
  headers.set("etag", object.httpEtag);
  // The key is immutable (a new ULID per uploaded image): it can be cached forever.
  headers.set("cache-control", "public, max-age=31536000, immutable");
  return new Response(object.body, { headers });
});
